      "ballot_id": "B004",
      "proposed_laureates": [
        "Lap-Chee Tsui",
        "John R. Riordan",
        "Francis S. Collins"
      ],
      "assessment": {
        "nobel_worthiness": "Identification of CFTR established the molecular basis of a common lethal inherited disease and reshaped molecular medicine.",
        "attribution": "Tsui, Riordan, and Collins represent major complementary roles in the mapping, cloning, and identification effort.",
        "maturity": "The causal assignment is definitive and has supported extensive mechanistic work and successful disease-modifying therapies.",
        "uncertainties": [
          "The discovery involved a broad collaborative effort, making the allocation of priority among contributors inherently compressed."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Brian J. Druker",
        "Nicholas B. Lydon",
        "Charles L. Sawyers"
      ],
      "assessment": {
        "nobel_worthiness": "BCR-ABL inhibition made molecularly targeted cancer therapy a durable clinical reality and transformed chronic myeloid leukemia outcomes.",
        "attribution": "Lydon made a key contribution to development of the inhibitor, Druker to clinical translation, and Sawyers to defining and overcoming resistance mechanisms.",
        "maturity": "Long-term clinical experience and a deep mechanistic record establish both efficacy and the general significance of the paradigm.",
        "uncertainties": [
          "The respective contributions of disease biology, drug discovery, and clinical translation are difficult to separate cleanly."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Marc Feldmann",
        "Ravinder N. Maini"
      ],
      "assessment": {
        "nobel_worthiness": "TNF blockade converted mechanistic insight into a highly consequential treatment paradigm for rheumatoid arthritis and other inflammatory diseases.",
        "attribution": "Feldmann and Maini jointly linked TNF biology to therapeutic intervention and provided decisive clinical validation.",
        "maturity": "The approach has extensive clinical validation, sustained impact, and broad application across inflammatory conditions.",
        "uncertainties": [
          "TNF biology and therapeutic development drew on many foundational contributors beyond the two proposed laureates."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B025",
      "proposed_laureates": [
        "F. Ulrich Hartl",
        "Arthur L. Horwich"
      ],
      "assessment": {
        "nobel_worthiness": "Chaperonin-assisted folding revealed a fundamental cellular solution to the protein-folding problem, with broad implications for disease biology.",
        "attribution": "Hartl and Horwich made complementary seminal contributions to demonstrating and explaining chaperonin-mediated protein folding.",
        "maturity": "The central mechanism has been repeatedly established structurally, biochemically, and across diverse biological systems.",
        "uncertainties": [
          "The conceptual and experimental lineage includes important earlier work on molecular chaperones more broadly."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Kazutoshi Mori",
        "Peter Walter"
      ],
      "assessment": {
        "nobel_worthiness": "The unfolded protein response defined how cells detect endoplasmic-reticulum stress and restore proteostasis, a central principle of cell physiology.",
        "attribution": "Mori and Walter provided foundational, complementary elucidation of signaling from the stressed endoplasmic reticulum.",
        "maturity": "Core pathway architecture and downstream physiological relevance are firmly established in multiple organisms and disease settings.",
        "uncertainties": [
          "The pathway comprises several branches and a wider network of contributors, complicating a fully comprehensive attribution."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Jacques F. A. P. Miller",
        "Max D. Cooper"
      ],
      "assessment": {
        "nobel_worthiness": "Recognition of distinct B- and T-lymphocyte lineages established the basic organization of adaptive immunity.",
        "attribution": "Miller's work on thymus-dependent immunity and Cooper's identification of distinct lymphocyte systems constitute the principal complementary contributions.",
        "maturity": "The finding is a foundational and repeatedly confirmed framework for modern immunology and clinical medicine.",
        "uncertainties": [
          "Its longstanding foundational status raises timing questions, and subsequent immunological work greatly expanded the original framework."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Richard O. Hynes",
        "Erkki Ruoslahti",
        "Timothy A. Springer"
      ],
      "assessment": {
        "nobel_worthiness": "Integrins supplied the molecular explanation for pivotal cell-matrix and cell-cell adhesion processes throughout physiology, immunity, and disease.",
        "attribution": "Hynes, Ruoslahti, and Springer made major complementary contributions to identifying integrins and defining their biological functions.",
        "maturity": "The receptor family and its roles are deeply validated across cell biology, development, hemostasis, and immunology.",
        "uncertainties": [
          "The field's broad, distributed discovery history makes the three-person attribution necessarily selective."
        ]
      }
    }
  ]
